using System.Text.Json;
using RAWSelectionAssistant.Core.Services.Color;
using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Tests;
[TestClass]public sealed class R53PhotographicBlendTests
{
 [TestMethod]public void ExplicitV2ModesRespectOpacityMaskLegacyAndHdrBoundary(){using var a=new HighBitDepthImageBuffer(1,1,new float[]{.2f,.5f,.8f});using var effect=new HighBitDepthImageBuffer(1,1,new float[]{.7f,.1f,.6f});foreach(var mode in new[]{StudioLayerBlend.Overlay,StudioLayerBlend.SoftLight,StudioLayerBlend.Darken,StudioLayerBlend.Lighten,StudioLayerBlend.Color,StudioLayerBlend.Luminosity}){var n=new ColorAdjustmentStackNode(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"v2"){CompositeVersion=2,Blend=mode,Opacity=.6};using var actual=StudioLayerComposite.Apply(a,effect,n);var mixed=PhotographicBlendV2.Blend(new(.2f,.5f,.8f),new(.7f,.1f,.6f),mode);for(int i=0;i<3;i++)Assert.AreEqual(a.Rgb32.Span[i]+(new[]{mixed.X,mixed.Y,mixed.Z}[i]-a.Rgb32.Span[i])*.6,actual.Rgb32.Span[i],1e-6);var restored=JsonSerializer.Deserialize<ColorAdjustmentStackNode>(JsonSerializer.Serialize(n))!;restored.Normalize();using var again=StudioLayerComposite.Apply(a,effect,restored);CollectionAssert.AreEqual(actual.Rgb32.ToArray(),again.Rgb32.ToArray());using var zero=StudioLayerComposite.Apply(a,effect,n with{Opacity=0});CollectionAssert.AreEqual(a.Rgb32.ToArray(),zero.Rgb32.ToArray());Assert.ThrowsExactly<InvalidDataException>(()=>(n with{CompositeVersion=1}).Normalize());}
 using var hdr=new HighBitDepthImageBuffer(1,1,new float[]{-1,2,4});using var keep=StudioLayerComposite.Apply(hdr,effect,new(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"hdr"){CompositeVersion=2,Opacity=0,Blend=StudioLayerBlend.Overlay});CollectionAssert.AreEqual(hdr.Rgb32.ToArray(),keep.Rgb32.ToArray());
 }
 [TestMethod]public void ProduceFixedRgbBlendReferenceCases(){var dir=Environment.GetEnvironmentVariable("KITAO_HOME_SCENE_EVIDENCE");if(dir is null){Assert.Inconclusive("Explicit matrix output required");return;}var rows=new List<object>();foreach(var mode in new[]{StudioLayerBlend.Overlay,StudioLayerBlend.SoftLight,StudioLayerBlend.Darken,StudioLayerBlend.Lighten,StudioLayerBlend.Color,StudioLayerBlend.Luminosity})foreach(int a in new[]{0,1,16,64,128,192,254,255})foreach(int b in new[]{0,1,16,64,128,192,254,255}){var x=new ColorVector3(a/255d,(255-a)/255d,.35);var y=new ColorVector3(b/255d,.25,(255-b)/255d);var v=PhotographicBlendV2.Blend(x,y,mode);rows.Add(new{mode=mode.ToString(),a=new[]{x.X,x.Y,x.Z},b=new[]{y.X,y.Y,y.Z},actual=new[]{v.X,v.Y,v.Z}});}Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"BLEND_V2_REFERENCE_INPUT.json"),JsonSerializer.Serialize(rows));}
}
